import sys

def is_odd_digit(d):
    return d % 2 == 1

def count_odd_digits(n):
    return sum(is_odd_digit(int(d)) for d in str(n))

def find_kth_magical(K):
    count = 0
    n = 0
    while count < K:
        n += 1
        if count_odd_digits(n) % 2 == 0:
            count += 1
    return n

